# ghost text: prefix trie of learned completions (the serving shape)
trie = {}
for phrase in ('for i in range(', 'for x in items:', 'import os', 'def main():'):
    node = trie
    for ch in phrase:
        node = node.setdefault(ch, {})
    node['$'] = phrase

def complete(prefix):
    node = trie
    for ch in prefix:
        node = node.get(ch)
        if node is None:
            return None
    out = []
    def walk(n):
        for k, v in n.items():
            if k == '$':
                out.append(v)
            else:
                walk(v)
    walk(node)
    return out

print('ghost for "for ":', complete('for '))
