import hashlib

cache = {}

def complete(prefix, suffix):
    key = hashlib.md5(prefix.encode()).hexdigest()  # stable prefix
    if key not in cache:
        cache[key] = 'KV(len=%d)' % len(prefix)     # expensive, once
        cost = len(prefix) + len(suffix)
    else:
        cost = len(suffix)                          # cheap: reuse KV
    return 'answer (cost %d tokens, cached=%s)' % (cost, key in cache and len(cache) > 0)

prefix = 'system + file context (3000 tokens)'
print(complete(prefix, 'q1'))
print(complete(prefix, 'q2: follow-up'))
print('chat hit rates are high: same file, follow-up questions')

# providers check the mode BEFORE gathering context
mode = 'allowlist'
allowed = {'/work/api'}

def gather(path, content):
    if mode == 'local':
        return '(local model: nothing leaves)'
    if mode == 'allowlist' and path not in allowed:
        return '(blocked by allowlist: not shared)'
    return content[:40]

