models = {'fast': {'ms': 80, 'cost': 1}, 'large': {'ms': 2000, 'cost': 20}}

def route(task, budget_ms):
    if task == 'completion':
        return 'fast'  # always: latency-critical
    return 'large' if budget_ms > 1500 else 'fast'

for task, budget in (('completion', 100), ('chat-hard', 5000), ('chat-quick', 800)):
    m = route(task, budget)
    print('%-12s budget %4dms -> %s (%dms)' % (task, budget, m, models[m]['ms']))
print('one assistant UX, many engines underneath')
